    max_S = 0
    # Try all possible degree sequences? No, that's still too many.
    # Let's just try all graphs for n=4, 5, 6.
    # For n=4, there are 2^6 = 64 graphs.
    # For n=5, there are 2^10 = 1024 graphs.
    # For n=6, there are 2^15 = 32768 graphs.
    for i in range(1 << (n * (n - 1) // 2)):
        adj = [[False]*n for _ in range(n)]
